def dump_json(path: Path, data, pretty: bool = False) -> None:
    if pretty:
        text = json.dumps(data, ensure_ascii=False, indent=2) + "\n"
    else:
        text = json.dumps(data, ensure_ascii=False, separators=(",", ":")) + "\n"
    path.write_text(text, encoding="utf-8")


def to_simplified(text: str) -> str:
    out = []
    for i, ch in enumerate(text):
        simp = CC.convert(ch)
        # 「祇」作「只、仅」时简体作只。神祇、地祇，以及「皇地之祇」这种隔着「之」的，仍作祇。
        if ch == "祇":
            prev = text[i - 1] if i else ""
            prev2 = text[i - 2] if i >= 2 else ""
            if prev in ("神", "地") or (prev == "之" and prev2 in ("神", "地")):
                simp = "祇"
            else:
                simp = "只"
        if len(simp) != 1:
            raise SystemExit(f"简繁不对齐：{ch} -> {simp}")
        out.append(simp)
    text = "".join(out)
    # OpenCC 把卦名「乾」收成「干」。乾坤不是干湿的干。
    text = text.replace("干坤", "乾坤")
    text = text.replace("干刚", "乾刚")
    text = text.replace("干位", "乾位")
    text = text.replace("干象", "乾象")
    # 人名樊於期的於不是介词于。单独称「於期」也要留下。
    text = text.replace("樊于期", "樊於期").replace("于期太息", "於期太息")
    # 桑乾河的乾读 qián，不是干燥的干。
    text = text.replace("桑干", "桑乾")
    # 维基文库这一句没有顿号。代与光狼城是两处，取字管两者。
    return text.replace("取代光狼城", "取代、光狼城")


def clean_inline(text: str) -> str:
    text = text.replace("'''", "")
    text = re.sub(r"<!--.*?-->", "", text, flags=re.S)
    text = re.sub(r"-\{([^}]+)\}-", r"\1", text)
    text = re.sub(r"\[\[(?:[^|\]]+\|)?([^\]]+)\]\]", r"\1", text)
    # 卷六十六把年号写在 {{YL|}} 里；卷七十八用 {{僻字}} 拼孙吴太子的名字。先展开，再丢掉其余模板。
    text = re.sub(r"\{\{YL\|([^}]+)\}\}", r"\1", text)
    text = re.sub(r"\{\{僻字\|([^|}]+)\|[^}]+\}\}", r"\1", text)
    text = re.sub(r"\{\{\*\|(.*?)\}\}", r"（\1）", text)
    text = re.sub(r"\{\{[^}]+\}\}", "", text)
    text = text.translate(VARIANTS)
    return text


def classify_ref(ref: str, juan: int = 0) -> str:
    # 点读本把司马光未改的「蜀」逕改成「汉」。括号里留着的才是本文。
    if juan >= 69 and "司馬光未改" in ref:
        return "supplement"
    # 胡注指出「取魏、宋」脱去「晋」。通鉴用晋的年号纪事，从注补回。
    if juan >= 69 and "取魏" in ref and "胡注" in ref:
        return "restore"
    marks = WEI_RESTORE_MARK if juan >= 69 else RESTORE_MARK
    if any(mark in ref for mark in marks):
        return "restore"
    if any(mark in ref for mark in SUPPLEMENT_MARK):
        return "supplement"
    if re.search(r"增[。．]?$", ref.strip()):
        return "supplement"
    if "补" in ref or "補" in ref:
        return "supplement"
    return "emend"


def transform_segment(segment: str, kind: str) -> str:
    if kind == "supplement":
        # 增补、移入的〔〕不是司马光原文；括号里留着的才是要删改前的字。
        segment = re.sub(r"〔[^〕]*〕", "", segment)
        segment = re.sub(r"\(([^)]*)\)", r"\1", segment)
        return segment
    segment = re.sub(r"〔([^〕]*)〕\(([^)]*)\)", r"\1", segment)
    segment = re.sub(r"\([^)]{1,16}\)", "", segment)
    segment = re.sub(r"〔([^〕]*)〕", r"\1", segment)
    return segment


def tidy_text(text: str) -> str:
    text = re.sub(r"[ \t\u3000]+", "", text)
    text = text.replace("。」。", "。」")
    text = text.replace("！」！", "！」")
    text = text.replace("？」？", "？」")
    text = re.sub(r"，{2,}", "，", text)
    text = re.sub(r"。{2,}", "。", text)
    # 删掉增补的名单之后，顿号会贴在逗号或句号前面。
    text = text.replace("、，", "，").replace("、。", "。")
    # 代与光狼城是两处。维基文库这一句没有顿号，繁简都补上，避免对不齐。
    text = text.replace("取代光狼城", "取代、光狼城")
    # 维基文库用「□+部件」拼不出的字。按《史记》同段文字补成单字。
    # 卷九韩信对策：维基文库误点作「何所不誅以？天下城邑」，「以」属下句。
    text = text.replace("何所不誅以？天下城邑", "何所不誅！以天下城邑")
