def restore_sunce_kuaiji(text: str) -> str:
    """卷六十二整理者把孙策取会稽移到「曹操在许」之前。胡注本仍在立宗庙于许之后，改回。"""
    start = text.find("'''8'''\u3000孫策將取會稽")
    end = text.find("'''9'''\u3000曹操在許")
    mark = "始立宗廟社稷於許。"
    ins = text.find(mark)
    if start < 0 or end < 0 or ins < 0 or not (start < end < ins):
        raise SystemExit(f"卷六十二孙策段落无法归位 {start, end, ins}")
    block = text[start:end]
    if not block.endswith("\n"):
        block += "\n"
    text = text[:start] + text[end:ins + len(mark)] + "\n\n" + block + text[ins + len(mark):]
    return text


def year_heading_line(raw: str) -> str | None:
    """卷六十六、六十七等卷把年份写成普通行，不放在 == 标题里。"""
    line = clean_inline(raw).strip()
    line = re.sub(r"\s+", "", line).strip("*＊")
    if not line or len(line) > 48 or any(ch in line for ch in "。！？；"):
        return None
    if "年" not in line:
        return None
    trial = strip_emperor_prefix(line)
    if YEAR_RE.match(trial):
        return line
    return None


def parse_juan(juan: int, text: str) -> tuple[str, list[dict]]:
    # 卷四十五维基文库把「斬首數百級」断在两段之间。
    text = text.replace("往赴之，斬\n\n首數百級", "往赴之，斬首數百級")
    # 卷五十维基文库年份标题漏「延光」。
    text = text.replace("孝安皇帝三年（甲子，公元一二四）", "孝安皇帝延光三年（甲子，公元一二四）")
    # 卷五十二维基文库段间夹有单独的 <BR> 行，另混入残缺帝号行「漢孝皇帝」（应为孝沖皇帝题名）。
    text = re.sub(r"^(?:<BR>|漢孝皇帝)[ \t]*$", "", text, flags=re.M)
    # 卷五十六维基文库：「以司空橋玄為司徒」段末误作分号；「帝以竇太后有援立之功，」与下段「冬，十月」本是一句，被拆成两段。
    text = text.replace("以司空橋玄為司徒；\n", "以司空橋玄為司徒。\n")
    text = text.replace("援立之功，\n\n冬，十月，戊子朔，", "援立之功，冬，十月，戊子朔，")
    if juan == 62:
        text = restore_sunce_kuaiji(text)
    if juan == 72:
        # 点读本把「庲降都督张翼」和「用法严峻」断成两行，逗号落在下一行。
        text = text.replace(
            "〔漢〕(蜀)庲降都督張翼<ref>〔漢〕(蜀)庲降都督張翼　此處司馬光未改「蜀」為「漢」，逕改。</ref>\n，用法嚴峻",
            "〔漢〕(蜀)庲降都督張翼，用法嚴峻<ref>〔漢〕(蜀)庲降都督張翼　此處司馬光未改「蜀」為「漢」，逕改。</ref>",
        )
    for old, new, count in JUAN_TRAD_FIXES.get(juan, []):
        assert text.count(old) == count, (juan, old, text.count(old))
        text = text.replace(old, new)
    for old, new, count in JUAN_SENSE_FIXES.get(juan, []):
        assert text.count(old) == count, (juan, old, text.count(old))
        text = text.replace(old, new)
    span = ""
    years: list[dict] = []
    last_king = ""
    current: dict | None = None
    stopped = False
    for raw in text.splitlines():
        heading_match = HEADING_RE.match(raw.strip())
        if heading_match:
            level = len(heading_match.group(1))
            title_raw = heading_match.group(2)
            if STOP_RE.search(clean_inline(title_raw)):
                stopped = True
                current = None
                continue
            if level == 1 and ("纪" in title_raw or "紀" in title_raw):
                current = None
                continue
            last_king, meta = parse_heading(title_raw, last_king)
            current = None
            if meta:
                meta["paragraphs_t"] = []
                years.append(meta)
                current = meta
            continue
        if stopped:
            continue
        stripped = raw.strip()
        if stripped in {"__TOC__", "__NOTOC__"} or stripped.startswith(("{{", "[[", "|")):
            continue
        plain_year = year_heading_line(raw)
        if plain_year and not heading_match:
            last_king, meta = parse_heading(plain_year, last_king)
            current = None
            if meta:
                meta["paragraphs_t"] = []
                years.append(meta)
                current = meta
            continue
        if stripped.startswith("'''起") and not span:
            span = apply_emendations(clean_inline(stripped), juan)
            continue
        span_line = clean_inline(stripped)
        span_line = re.sub(r"\s+", "", span_line)
        if not span and re.fullmatch(r".{0,12}起.+凡[^。]{1,12}年。?", span_line):
            matched_span = re.search(r"起.+凡[^。]{1,12}年。?", span_line)
            if matched_span:
                span = apply_emendations(matched_span.group(0), juan)
                continue
        if re.fullmatch(r"資治通鑑第?\d+卷", span_line):
            continue
        if current is None:
            continue
        # 卷四十四正文中夹着一行帝号小标题「顯宗孝明皇帝上」，不是正文。
        if re.fullmatch(r"(?:漢)?(?:世祖光武|顯宗孝明|肅宗孝章|孝和|孝殤|孝安|孝順|孝顺|孝質|孝桓|孝靈|孝灵|孝獻|孝献)皇帝(?:[上中下]之[上中下]|[上中下]+|[甲乙丙丁戊己庚辛壬癸])", stripped):
            continue
        # 卷六十九起卷首另起一行的帝号，不是正文。
        title_line = re.sub(r"\s+", "", clean_inline(stripped)).strip("*＊")
        if re.fullmatch(r"(?:世祖文皇帝|烈祖明皇帝|邵陵厲公|高貴鄉公|元皇帝).{0,8}", title_line):
            continue
        # 卷三十三：维基文库在建平元年标题前多出一行帝号「孝哀皇帝上」，不是正文。
        if re.fullmatch(r"(?:孝.皇帝|王莽)[上中下]", stripped):
            continue
        paragraph = paragraph_from_line(raw, juan)
        if paragraph:
            current["paragraphs_t"].append(paragraph)
    kept = []
    for year in years:
        paragraphs = []
        for paragraph in year["paragraphs_t"]:
            sentences = split_sentences(paragraph)
            if sentences:
                paragraphs.append(sentences)
        if not paragraphs:
            continue
        year["paragraphs_t"] = paragraphs
        kept.append(year)
    return span, kept


def tokens_for(trad: str, simp: str) -> list[dict]:
    rows = []
    for t_ch, s_ch in zip(trad, simp):
        if t_ch in PUNCT or s_ch in PUNCT:
            rows.append({"t": t_ch, "s": s_ch, "punct": True})
        else:
            rows.append({"t": t_ch, "s": s_ch, "py": "", "ctx": "", "pos": "", "extra": "", "level": "dict"})
    fix_readings(rows)
    return rows


def load_years() -> list[dict]:
    entries = []
    for juan in range(1, LAST_JUAN + 1):
        path = SRC / f"juan{juan:02d}.wikitext"
        span, years = parse_juan(juan, path.read_text(encoding="utf-8"))
        for index, year in enumerate(years, 1):
            paragraphs_s = []
            for paragraph in year["paragraphs_t"]:
                paragraphs_s.append([to_simplified(sent) for sent in paragraph])
            title_s = to_simplified(year["title_t"])
            entries.append({
                "id": f"z{juan:02d}-{index:02d}",
                "juan": juan,
                "era": JUAN_ERA[juan],
                "index": index,
                "title_t": year["title_t"],
                "title_s": title_s,
                "date": year["date"],
                "ganzhi": to_simplified(year["ganzhi"]),
                "span": to_simplified(span),
                "paragraphs_t": year["paragraphs_t"],
                "paragraphs_s": paragraphs_s,
            })
    return entries


def sentence_count(entry: dict) -> int:
    return sum(len(paragraph) for paragraph in entry["paragraphs_s"])


def article_for(entry: dict, lesson: dict | None) -> dict:
    trs = list(lesson["trs"]) if lesson else []
    cursor = 0
    paragraphs = []
    for trad_p, simp_p in zip(entry["paragraphs_t"], entry["paragraphs_s"]):
        sentences = []
        for trad, simp in zip(trad_p, simp_p):
            if len(trad) != len(simp):
                raise SystemExit(f"{entry['id']} 简繁长度不一致：{trad} / {simp}")
            tr = trs[cursor] if cursor < len(trs) else ""
            cursor += 1
            sentences.append({"tr": tr, "tokens": tokens_for(trad, simp)})
        paragraphs.append({"sentences": sentences})
    art = {
        "id": entry["id"],
        "volume": entry["juan"],
        "volumeTitle": volume_title(entry),
        "volumeSubtitle": entry["date"] or "",
        "index": entry["index"],
        "title": {"t": entry["title_t"], "s": entry["title_s"]},
        "book": {"t": "資治通鑑", "s": "资治通鉴"},
        "sourceHead": {"t": source_head(entry, trad=True), "s": source_head(entry, trad=False)},
        "author": "司马光",
        "annotated": bool(lesson),
        "paragraphs": paragraphs,
    }
    if lesson:
        art["lesson"] = lesson["lesson"]
    return art


